"""Documentacao da 265a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, prova_save, resultado_pt_en

N = 265
R = [('gravar_financas', 'FinanceTable::save_finance_dat', '0x59b3b0', 'fin_prm.cpp', 'thiscall', 'grava no item finance.dat as finanças de todos os clubes (0x167 bytes × [0xae235c] de [this]); sem contêiner, nada; erro: a caixa "Error" (finance.CPP 0x115e, 0x1166) sem fechar o item', 'writes the finances of every club into the finance.dat item (0x167 bytes × [0xae235c] from [this]); no container, nothing; on error the "Error" box (finance.CPP 0x115e, 0x1166) without closing the item'), ('carregar_financas', 'FinanceTable::load_from_save', '0x59b2a0', 'fin_prm.cpp', 'thiscall', 'lê do item finance.dat as finanças de todos os clubes em [this] e devolve 1; sem contêiner 0; erro: a caixa "Error" (0x1137, 0x113f) e 0 (o construtor refaz as finanças do zero)', 'reads the finances of every club from the finance.dat item into [this] and returns 1; no container 0; on error the "Error" box (0x1137, 0x113f) and 0 (the constructor rebuilds the finances from scratch)'), ('gravar_gerente_de_elencos', 'SQUAD_MANAGER::save', '0x859cc0', 'squad_manager.cpp', 'thiscall', 'grava no item squad_manager.dat o u16 em +0 estendido a 4 bytes e devolve 1; erro: a caixa "Error" (squad_manager.cpp 0x68, 0x6f) e 0', 'writes the u16 at +0, widened to 4 bytes, into the squad_manager.dat item and returns 1; on error the "Error" box (squad_manager.cpp 0x68, 0x6f) and 0'), ('gravar_sementes_da_uefa', 'UefaSeeding::save_to_temp_file', '0x905510', 'uefa_seeding.cpp', 'thiscall', 'grava CM3_TEMP\\uefa_seeding.tmp: quantos países (+0x438), 0x12 bytes por país de +0, +0x439 (u16), quantos (+0x43f) u32 de [+0x43b] e 50 registros de 0xc de +0x440; erro: a caixa "Error" sem fechar o arquivo', 'writes CM3_TEMP\\uefa_seeding.tmp: the country count (+0x438), 0x12 bytes per country from +0, +0x439 (u16), as many u32 as +0x43f from [+0x43b] and 50 records of 0xc from +0x440; on error the "Error" box without closing the file'), ('gravar_sementes_da_conmebol', 'ConmebolSeeding::save_to_temp_file', '0x4c6b70', 'conmebol_seeding.cpp', 'thiscall', 'grava CM3_TEMP\\conmebol_seeding.tmp: quantos países (+0x6e), 0xa bytes por país de +0, +0x6f (u16) e +0x71 (u32); erro: a caixa "Error" sem fechar o arquivo', 'writes CM3_TEMP\\conmebol_seeding.tmp: the country count (+0x6e), 0xa bytes per country from +0, +0x6f (u16) and +0x71 (u32); on error the "Error" box without closing the file'), ('gravar_paises_anfitrioes', 'HostCountry::save_temp_file', '0x5fb320', 'host_country.cpp', 'thiscall', 'grava CM3_TEMP\\HostCountry.tmp: quantos (+4, u16) e 0x22 bytes por anfitrião de [+0], sem conferir a gravação; erro ao abrir: a caixa "Error"', 'writes CM3_TEMP\\HostCountry.tmp: the count (+4, u16) and 0x22 bytes per host from [+0], without checking the writes; on open error the "Error" box'), ('gravar_historico_dos_clubes', 'Club_History::save', '0x443f50', 'club_history.cpp', 'thiscall', 'grava no item "club history.dat" a quantidade (+0xc) e os registros de 0x10 bytes de [+8] e devolve 1; sem contêiner a caixa "Error" e 0; erro ao abrir ou gravar: a caixa e o jogo para', 'writes the count (+0xc) and the 0x10-byte records from [+8] into the "club history.dat" item and returns 1; no container the "Error" box and 0; on open or write error the box and the game stops'), ('gravar_estatisticas_dos_arbitros', 'OfficialsManager::save_official_stats', '0x79bb80', 'officials_manager.cpp', 'thiscall', 'grava no item off.dat [0xae2390] árbitros (0x11 bytes de [+0]), [0xae2350] nações (0x102 bytes de [+0xc]) e um byte por árbitro de [+8]; devolve 1 no byte baixo; sem árbitros ou erro: a caixa "Error", fecha o item e 0', 'writes [0xae2390] officials (0x11 bytes from [+0]), [0xae2350] nations (0x102 bytes from [+0xc]) and one byte per official from [+8] into the off.dat item; returns 1 in the low byte; with no officials or on error the "Error" box, closes the item and 0'), ('gravar_estatisticas_simuladas', 'SimulatedStats::save', '0x84c680', 'simulated_stats.cpp', 'thiscall', 'grava no item simulated_stats.dat a quantidade (+0) e os registros de 0x44 bytes de [+4]; erro: a caixa "Error" sem fechar o item', 'writes the count (+0) and the 0x44-byte records from [+4] into the simulated_stats.dat item; on error the "Error" box without closing the item'), ('gravar_datas_dos_clubes', 'fix_man_save_club_dates', '0x5af040', 'fix_man.cpp', 'cdecl', 'grava em CM3_TEMP\\club_dates.tmp a tabela [0xae2a5c], uma palavra por clube ([0xae235c]); sem a tabela ou com gravação curta, a caixa "Error" (fix_man.cpp 0x1011, 0x101b)', 'writes the [0xae2a5c] table, one word per club ([0xae235c]), into CM3_TEMP\\club_dates.tmp; without the table or on a short write, the "Error" box (fix_man.cpp 0x1011, 0x101b)'), ('carregar_datas_dos_clubes', 'fix_man_load_club_dates', '0x5aee90', 'fix_man.cpp', 'cdecl', 'aloca a tabela [0xae2a5c] (uma palavra por clube) e a lê de CM3_TEMP\\club_dates.tmp, ou a zera sem o arquivo; já alocada, sem memória ou com leitura curta, a caixa "Error" (0xfe4, 0xfec, 0xff6)', 'allocates the [0xae2a5c] table (one word per club) and reads it from CM3_TEMP\\club_dates.tmp, or zeroes it without the file; already allocated, out of memory or on a short read, the "Error" box (0xfe4, 0xfec, 0xff6)'), ('gravar_conferencia_das_pernas', 'fix_man_save_fixture_leg_checks', '0x5af4a0', 'fix_man.cpp', 'cdecl', 'com a lista [0xae2a48] não vazia, grava em CM3_TEMP\\check_fixture_legs.tmp a conta (2 bytes) e os itens de 15 bytes; gravação curta de um item, a caixa "Error" (0x10e0)', 'with the [0xae2a48] list not empty, writes the count (2 bytes) and the 15-byte items into CM3_TEMP\\check_fixture_legs.tmp; on a short item write, the "Error" box (0x10e0)')]
ESCAPADAS = {}  # nome: (explicação pt, explicação en), quando houver
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia com divergência ou carreira que não chegou à data'
RES_PT, RES_EN = resultado_pt_en(N)
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
PS = prova_save(N)  # leva do save: mutações e prova pelo .qst gravado com e sem as rotinas (cadeia.sh)
VIA_PT = 'pela prova do save' if PS else 'pela carreira até 2002-06-01, confirmando no modo comparação as que escapam'
VIA_EN = 'by the save proof' if PS else 'by the career to 2002-06-01, confirming the escaped ones in comparison mode'
PS_PT = f'Prova do save (o .qst com e sem as rotinas): {PS}. ' if PS else ''
PS_EN = f'Save proof (the .qst with and without the routines): {PS.replace("IGUAL", "EQUAL").replace("DIFERENTE", "DIFFERENT")}. ' if PS else ''
M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"{RES_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"{RES_EN}")
fazer(N, 1497, 1497 + len(R), 'o save das finanças e do gerente de elencos: gravar e carregar o finance.dat e gravar o squad_manager.dat; os temporários do save: as sementes da UEFA e da CONMEBOL e os países anfitriões; o save dos históricos: o histórico dos clubes, as estatísticas dos árbitros e as estatísticas simuladas; o save do calendário: gravar e carregar as datas dos clubes e gravar a conferência das pernas', 'saving the finances and the squad manager: writing and reading finance.dat and writing squad_manager.dat; the saved game temporary files: the UEFA and CONMEBOL seedings and the host countries; saving the histories: the club history, the officials statistics and the simulated statistics; saving the fixture calendar: writing and reading the club dates and writing the leg checks',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'o save das finanças e do gerente de elencos: gravar e carregar o finance.dat e gravar o squad_manager.dat; os temporários do save: as sementes da UEFA e da CONMEBOL e os países anfitriões; o save dos históricos: o histórico dos clubes, as estatísticas dos árbitros e as estatísticas simuladas; o save do calendário: gravar e carregar as datas dos clubes e gravar a conferência das pernas', 'saving the finances and the squad manager: writing and reading finance.dat and writing squad_manager.dat; the saved game temporary files: the UEFA and CONMEBOL seedings and the host countries; saving the histories: the club history, the officials statistics and the simulated statistics; saving the fixture calendar: writing and reading the club dates and writing the leg checks', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[('FinanceTable +0: as finanças dos clubes (0x167 bytes por clube, [0xae235c] clubes, nat_club inclusive); ponteiro; lê e grava no save (gravar_financas), grava do save (carregar_financas)', 'FinanceTable +0: the club finances (0x167 bytes per club, [0xae235c] clubs, nat_club included); pointer; reads and writes into the save (gravar_financas), writes from the save (carregar_financas)'), ('SQUAD_MANAGER +0: o valor do gerente de elencos (u16; 0 no jogo novo); valor; lê e grava no save em 4 bytes (gravar_gerente_de_elencos)', 'SQUAD_MANAGER +0: the squad manager value (u16; 0 in a new game); value; reads and writes into the save as 4 bytes (gravar_gerente_de_elencos)'), ('[0xae235c] quantidade de clubes; valor; lê (gravar_financas, carregar_financas)', '[0xae235c] club count; value; reads (gravar_financas, carregar_financas)'), ('UefaSeeding +0: países (0x12 bytes cada); +0x438 quantos (i8); +0x439 (u16); +0x43b ponteiro dos u32 e +0x43f quantos (i8); +0x440 50 registros de 0xc; bytes; lê e grava no uefa_seeding.tmp (gravar_sementes_da_uefa)', 'UefaSeeding +0: countries (0x12 bytes each); +0x438 count (i8); +0x439 (u16); +0x43b pointer to the u32s and +0x43f count (i8); +0x440 50 records of 0xc; bytes; reads and writes into uefa_seeding.tmp (gravar_sementes_da_uefa)'), ('ConmebolSeeding +0: países (0xa bytes cada); +0x6e quantos (i8); +0x6f (u16); +0x71 (u32); bytes; lê e grava no conmebol_seeding.tmp (gravar_sementes_da_conmebol)', 'ConmebolSeeding +0: countries (0xa bytes each); +0x6e count (i8); +0x6f (u16); +0x71 (u32); bytes; reads and writes into conmebol_seeding.tmp (gravar_sementes_da_conmebol)'), ('HostCountry +0: anfitriões (0x22 bytes cada); ponteiro; +4 quantos (i16); lê e grava no HostCountry.tmp (gravar_paises_anfitrioes)', 'HostCountry +0: hosts (0x22 bytes each); pointer; +4 count (i16); reads and writes into HostCountry.tmp (gravar_paises_anfitrioes)'), ('Club_History +8: os registros do histórico de liga e copa dos clubes (0x10 bytes cada); ponteiro; +0xc quantos (u32); lê e grava no save (gravar_historico_dos_clubes)', 'Club_History +8: the club league and cup history records (0x10 bytes each); pointer; +0xc count (u32); reads and writes into the save (gravar_historico_dos_clubes)'), ('OfficialsManager +0: estatísticas por árbitro (0x11 bytes); +0xc por nação (0x102 bytes); +8 um byte por árbitro; ponteiros; [0xae2390] árbitros e [0xae2350] nações; lê e grava no off.dat (gravar_estatisticas_dos_arbitros)', 'OfficialsManager +0: per-official stats (0x11 bytes); +0xc per nation (0x102 bytes); +8 one byte per official; pointers; [0xae2390] officials and [0xae2350] nations; reads and writes into off.dat (gravar_estatisticas_dos_arbitros)'), ('SimulatedStats +0: quantos (u32); +4 os registros de 0x44 bytes; ponteiro; lê e grava no save (gravar_estatisticas_simuladas)', 'SimulatedStats +0: count (u32); +4 the 0x44-byte records; pointer; reads and writes into the save (gravar_estatisticas_simuladas)'), ('[0xae2a5c] as datas dos clubes (uma palavra por clube: bit 0 o primeiro ano, o resto o último); ponteiro; lê e grava no save (gravar_datas_dos_clubes), aloca e grava da carga (carregar_datas_dos_clubes)', '[0xae2a5c] the club dates (one word per club: bit 0 the first year, the rest the last); pointer; reads and writes into the save (gravar_datas_dos_clubes), allocates and writes from the load (carregar_datas_dos_clubes)'), ('[0xae2a48] a lista de conferência das pernas (LLIST: +0 conta, +2 cabeça, +0xa cursor; itens de 15 bytes); lê e grava o cursor (gravar_conferencia_das_pernas)', '[0xae2a48] the fixture leg check list (LLIST: +0 count, +2 head, +0xa cursor; 15-byte items); reads and writes the cursor (gravar_conferencia_das_pernas)'), ('[0xae235c] quantidade de clubes; valor; lê (gravar_datas_dos_clubes, carregar_datas_dos_clubes)', '[0xae235c] club count; value; reads (gravar_datas_dos_clubes, carregar_datas_dos_clubes)')], interessa=['SGE', 'CMRTE'])
